import axios from 'axios';

export const fetchPlace = async (id) => {
    try {
        const response = await axios.get(`http://localhost:5000/api/places/${id}`);
        return response.data;
    } catch (error) {
        console.error(`Error fetching place with ID ${id}:`, error);
        throw error;
    }
};
